cd /testbed && python - <<'PY'
from pathlib import Path
import re
path = Path('sklearn/utils/_show_versions.py')
text = path.read_text(encoding='utf-8')
# Insert joblib after sklearn in deps list
text2 = re.sub(r'(\n\s*deps = \[\n(?:\s*".*",\n)*\s*"sklearn",\n)', r'\1        "joblib",\n', text, count=1)
if text2 == text:
    raise SystemExit('Failed to insert joblib into deps list')
text = text2
# Replace the import loop with joblib-aware logic
pattern = re.compile(r"""\n\s*for modname in deps:\n\s*try:\n\s*if modname in sys\.modules:\n\s*mod = sys\.modules\[modname\]\n\s*else:\n\s*mod = importlib\.import_module\(modname\)\n\s*ver = get_version\(mod\)\n\s*deps_info\[modname\] = ver\n\s*except ImportError:\n\s*deps_info\[modname\] = None\n""", re.M)
replacement = """

    for modname in deps:
        try:
            if modname == "joblib":
                # joblib used to be vendored in scikit-learn under
                # ``sklearn.externals.joblib``.
                if "joblib" in sys.modules:
                    mod = sys.modules["joblib"]
                else:
                    try:
                        mod = importlib.import_module("joblib")
                    except ImportError:
                        mod = importlib.import_module("sklearn.externals.joblib")
            else:
                if modname in sys.modules:
                    mod = sys.modules[modname]
                else:
                    mod = importlib.import_module(modname)
            ver = get_version(mod)
            deps_info[modname] = ver
        except ImportError:
            deps_info[modname] = None
"""
text2, n = pattern.subn(replacement, text, count=1)
if n != 1:
    raise SystemExit(f'Failed to replace loop (replaced {n} occurrences)')
path.write_text(text2, encoding='utf-8')
PY

